  2315  static const uint8_t *get_ls_tile_buffers(
  2316      AV1Decoder *pbi, const uint8_t *data, const uint8_t *data_end,
  2317      TileBufferDec (*const tile_buffers)[MAX_TILE_COLS]) {
  2318    AV1_COMMON *const cm = &pbi->common;
  2319    const int tile_cols = cm->tiles.cols;
  2320    const int tile_rows = cm->tiles.rows;
  2321    const int have_tiles = tile_cols * tile_rows > 1;
  2322    const uint8_t *raw_data_end;  // The end of the last tile buffer
  2323
  2324    if (!have_tiles) {
  2325      const size_t tile_size = data_end - data;
  2326      tile_buffers[0][0].data = data;
  2327      tile_buffers[0][0].size = tile_size;
  2328      raw_data_end = NULL;
  2329    } else {
  2330      // We locate only the tile buffers that are required, which are the ones
  2331      // specified by pbi->dec_tile_col and pbi->dec_tile_row. Also, we always
  2332      // need the last (bottom right) tile buffer, as we need to know where the
  2333      // end of the compressed frame buffer is for proper superframe decoding.
  2334
  2335      const uint8_t *tile_col_data_end[MAX_TILE_COLS] = { NULL };
  2336      const uint8_t *const data_start = data;
  2337
  2338      const int dec_tile_row = AOMMIN(pbi->dec_tile_row, tile_rows);
  2339      const int single_row = pbi->dec_tile_row >= 0;
  2340      const int tile_rows_start = single_row ? dec_tile_row : 0;
  2341      const int tile_rows_end = single_row ? tile_rows_start + 1 : tile_rows;
  2342      const int dec_tile_col = AOMMIN(pbi->dec_tile_col, tile_cols);
  2343      const int single_col = pbi->dec_tile_col >= 0;
  2344      const int tile_cols_start = single_col ? dec_tile_col : 0;
  2345      const int tile_cols_end = single_col ? tile_cols_start + 1 : tile_cols;
  2346
  2347      const int tile_col_size_bytes = pbi->tile_col_size_bytes;
  2348      const int tile_size_bytes = pbi->tile_size_bytes;
  2349      int tile_width, tile_height;
  2350      av1_get_uniform_tile_size(cm, &tile_width, &tile_height);
  2351      const int tile_copy_mode =
  2352          ((AOMMAX(tile_width, tile_height) << MI_SIZE_LOG2) <= 256) ? 1 : 0;
  2353      // Read tile column sizes for all columns (we need the last tile buffer)
  2354      for (int c = 0; c < tile_cols; ++c) {
  2355        const int is_last = c == tile_cols - 1;
  2356        size_t tile_col_size;
  2357
  2358        if (!is_last) {
  2359          tile_col_size = mem_get_varsize(data, tile_col_size_bytes);
  2360          data += tile_col_size_bytes;
  2361          tile_col_data_end[c] = data + tile_col_size;
  2362        } else {
  2363          tile_col_size = data_end - data;
  2364          tile_col_data_end[c] = data_end;
  2365        }
  2366        data += tile_col_size;
  2367      }
  2368
  2369      data = data_start;
  2370
  2371      // Read the required tile sizes.
  2372      for (int c = tile_cols_start; c < tile_cols_end; ++c) {
  2373        const int is_last = c == tile_cols - 1;
  2374
  2375        if (c > 0) data = tile_col_data_end[c - 1];
  2376
  2377        if (!is_last) data += tile_col_size_bytes;
  2378
  2379        // Get the whole of the last column, otherwise stop at the required tile.
  2380        for (int r = 0; r < (is_last ? tile_rows : tile_rows_end); ++r) {
  2381          get_ls_tile_buffer(tile_col_data_end[c], &pbi->common.error, &data,
  2382                             tile_buffers, tile_size_bytes, c, r, tile_copy_mode);
  2383        }
  2384      }
  2385
  2386      // If we have not read the last column, then read it to get the last tile.
  2387      if (tile_cols_end != tile_cols) {
  2388        const int c = tile_cols - 1;
  2389
  2390        data = tile_col_data_end[c - 1];
  2391
  2392        for (int r = 0; r < tile_rows; ++r) {
  2393          get_ls_tile_buffer(tile_col_data_end[c], &pbi->common.error, &data,
  2394                             tile_buffers, tile_size_bytes, c, r, tile_copy_mode);
  2395        }
  2396      }
  2397      raw_data_end = data;
  2398    }
  2399    return raw_data_end;
